DROP TABLE IF EXISTS `building`;

CREATE TABLE `building` (
  `building_id` bigint(20) NOT NULL COMMENT '楼栋id',
  `building_name` varchar(32) DEFAULT NULL COMMENT '楼栋名称',
  `building_code` varchar(32) DEFAULT NULL COMMENT '楼栋编码',
  `building_acreage` decimal(32,10) DEFAULT NULL COMMENT '楼栋面积',
  `community_id` bigint(20) DEFAULT NULL COMMENT '小区id',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`building_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='楼栋 ';

